package io.translab.tantor.server.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.translab.tantor.server.domain.Task;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static io.translab.tantor.server.service.KafkaExpansionWorkflow.*;

class KafkaExpansionNativeEvidenceTest {
    final ObjectMapper mapper=new ObjectMapper().findAndRegisterModules();
    final KafkaExpansionNativeEvidence evidence=new KafkaExpansionNativeEvidence(mapper);
    @Test void controllerProofUsesAnExplicitIsoTimestampIndependentOfMapperDefaults()throws Exception{var proof=new KafkaExpansionLiveVerifier.ControllerProof(UUID.randomUUID(),UUID.randomUUID(),"a".repeat(64),102,"b".repeat(22),"c".repeat(64),Instant.now(),true,false);var wire=mapper.readTree(mapper.writeValueAsString(proof));assertTrue(wire.path("observedAt").isTextual());assertEquals(proof.observedAt(),Instant.parse(wire.path("observedAt").asText()));}
    Task issued()throws Exception{var task=new Task();task.setId(UUID.randomUUID());task.setHostId("candidate");task.setCommand(KafkaExpansionLedger.CANDIDATE);task.setStatus("SUCCESS");task.setParameters(mapper.writeValueAsString(Map.of("dispatch_expires_at",Instant.now().plusSeconds(120).toString())));return task;}
    ObjectNode report(KafkaExpansionPlan.Frozen frozen){var plan=frozen.plan();var process=plan.process("controller");var report=mapper.createObjectNode();report.put("observedAt",Instant.now().toString());var receipt=report.putObject("receipt");receipt.put("schemaVersion","add-quorum-candidate/v1");receipt.put("operationId",plan.operationId().toString());receipt.put("planDigest",frozen.digest());receipt.put("hostId",plan.candidateHostId());receipt.put("role","controller");receipt.put("nodeId",process.nodeId());receipt.put("kafkaClusterId",plan.kafkaClusterId());receipt.put("unit",plan.unit("controller"));receipt.put("configPath",plan.configPath("controller"));receipt.put("phase","STARTED");var state=report.putObject("observation");state.put("storageState","MATCHING");state.put("configOwned",true);state.put("unitOwned",true);state.put("serviceActive",true);state.put("runtimeVerified",true);var dirs=state.putObject("directoryIds");var paths=new LinkedHashSet<>(process.dataPaths());if(process.metadataPath()!=null&&!process.metadataPath().isEmpty())paths.add(process.metadataPath());int index=0;for(var path:paths)dirs.put(path,"a".repeat(21)+(char)('b'+index++));receipt.set("directoryIds",dirs.deepCopy());String metadata=process.metadataPath()==null||process.metadataPath().isEmpty()?process.dataPaths().getFirst():process.metadataPath();state.put("metadataDirectoryId",dirs.path(metadata).asText());return report;}
    @Test void matchingStorageAndReceiptPermitRunningProof()throws Exception{var frozen=new KafkaExpansionPlanTest().plan().freeze(mapper);var task=issued();task.setLogOutput(mapper.writeValueAsString(report(frozen)));assertDoesNotThrow(()->evidence.runningCandidate(evidence.read(frozen,"candidate:controller",task,task)));}
    @Test void foreignOperationWrongTaskAndExpiredEvidenceCannotAdvance()throws Exception{var frozen=new KafkaExpansionPlanTest().plan().freeze(mapper);for(String change:List.of("operation","task","time","unit","metadata")){var task=issued();var result=issued();result.setId(task.getId());var report=report(frozen);switch(change){case "operation"->((ObjectNode)report.path("receipt")).put("operationId",UUID.randomUUID().toString());case "task"->result.setId(UUID.randomUUID());case "time"->report.put("observedAt",Instant.now().minusSeconds(61).toString());case "unit"->((ObjectNode)report.path("receipt")).put("unit","controller.service");case "metadata"->((ObjectNode)report.path("observation")).put("metadataDirectoryId","z".repeat(22));}result.setLogOutput(mapper.writeValueAsString(report));assertThrows(IllegalStateException.class,()->evidence.read(frozen,"candidate:controller",task,result),change);}}
    @Test void partialStorageAndUnpinnedFormatIntentCannotConfirmFormatting()throws Exception{var frozen=new KafkaExpansionPlanTest().plan().freeze(mapper);var task=issued();var report=report(frozen);((ObjectNode)report.path("observation")).put("storageState","PARTIAL");task.setLogOutput(mapper.writeValueAsString(report));var proof=evidence.read(frozen,"candidate:controller",task,task);var step=frozen.steps().stream().filter(s->s.kind()==Kind.FORMAT&&s.target().equals("candidate:controller")).findFirst().orElseThrow();assertThrows(IllegalStateException.class,()->evidence.completed(frozen.plan(),step,proof,false));report=report(frozen);((ObjectNode)report.path("receipt")).put("phase","FORMAT_INTENT");task.setLogOutput(mapper.writeValueAsString(report));var uncertain=evidence.read(frozen,"candidate:controller",task,task);assertThrows(IllegalStateException.class,()->evidence.completed(frozen.plan(),step,uncertain,false));}
    @Test void voterAdmissionCannotBeAssertedByNativeReceiptAlone()throws Exception{var frozen=new KafkaExpansionPlanTest().plan().freeze(mapper);var task=issued();task.setLogOutput(mapper.writeValueAsString(report(frozen)));var proof=evidence.read(frozen,"candidate:controller",task,task);var step=frozen.steps().stream().filter(s->s.kind()==Kind.ADMIT).findFirst().orElseThrow();assertThrows(IllegalStateException.class,()->evidence.completed(frozen.plan(),step,proof,false));assertEquals(step.kind().requiredFacts(),evidence.completed(frozen.plan(),step,proof,true));}
}
